import{_ as e,r as n,o,c,e as s,a as l,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"{% partial %} - October CMS - 3.x","titleTemplate":false,"description":"Twig 标签","frontmatter":{"subtitle":"Twig 标签"},"headers":[{"level":2,"title":"变量","slug":"变量","link":"#变量","children":[]},{"level":2,"title":"将标记作为变量传递","slug":"将标记作为变量传递","link":"#将标记作为变量传递","children":[{"level":3,"title":"可组合部件","slug":"可组合部件","link":"#可组合部件","children":[]}]},{"level":2,"title":"将部件内容设置为 Twig 变量","slug":"将部件内容设置为-twig-变量","link":"#将部件内容设置为-twig-变量","children":[]},{"level":2,"title":"检查部件是否存在","slug":"检查部件是否存在","link":"#检查部件是否存在","children":[]}],"relativePath":"3.x/zh-cn/markup/tag/partial.md","filePath":"3.x/zh-cn/markup/tag/partial.md"}'),u={name:"3.x/zh-cn/markup/tag/partial.md"};function g(r,a,k,d,w,m){const t=n("pre-heading"),p=n("post-heading");return o(),c("div",null,[s(t),a[0]||(a[0]=l("h1",null,"{% partial %}",-1)),s(p),a[1]||(a[1]=i(`<p><code>{% partial %}</code> 标签将解析一个 <a href="./../../cms/themes/partials.html">CMS 部件</a>并在页面上渲染部件内容。要显示一个名为 <strong>footer.htm</strong> 的部件，只需在 <code>partial</code> 标签后以引号字符串的形式传递名称即可。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>footer<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>子目录中的部件也可以用同样的方式渲染。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>sidebar/menu<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><div class="custom-block tip"><p><a href="./../../cms/themes/themes.html">主题文档</a>有更多关于子目录用法的详细信息。</p></div><p>部件名称也可以是一个变量：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> tabName <span class="token operator">=</span> <span class="token string"><span class="token punctuation">&quot;</span>profile<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> tabName <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="变量"><a href="#变量" class="header-anchor">#</a> 变量</h2><p>你可以在部件名称后指定变量来向部件传递变量：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>blog-posts<span class="token punctuation">&quot;</span></span> posts<span class="token operator">=</span>posts <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>你也可以为部件分配新的变量：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>location<span class="token punctuation">&quot;</span></span> city<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Vancouver<span class="token punctuation">&quot;</span></span> country<span class="token operator">=</span><span class="token string"><span class="token punctuation">&quot;</span>Canada<span class="token punctuation">&quot;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>在部件内部，变量可以像任何其他标记变量一样被访问：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Country: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> country <span class="token delimiter punctuation">}}</span></span>, city: <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> city <span class="token delimiter punctuation">}}</span></span>.<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="将标记作为变量传递"><a href="#将标记作为变量传递" class="header-anchor">#</a> 将标记作为变量传递</h2><p>可以使用 <code>body</code> 属性将标记传递给部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    This is the card contents
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>然后内容可以作为 <code>body</code> 变量使用。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><h3 id="可组合部件"><a href="#可组合部件" class="header-anchor">#</a> 可组合部件</h3><p>可组合部件可以与 <code>{% placeholder %}</code> <a href="./placeholder.html">Twig 标签</a>结合使用来实现。以下部件定义了一个 <code>header</code> 和一个 <code>body</code> 区域，可以在其中添加 HTML 内容。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>header<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">placeholder</span> header <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>body<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> body<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>接下来，你可以在 <code>body</code> 内包含 <code>{% put %}</code> 标签，通过两个 HTML 内容区域来组合部件结果。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&quot;</span>card<span class="token punctuation">&quot;</span></span> body <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">put</span> header <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>h2</span><span class="token punctuation">&gt;</span></span>This is the card header<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>h2</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endput</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>This is the card contents<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endpartial</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="将部件内容设置为-twig-变量"><a href="#将部件内容设置为-twig-变量" class="header-anchor">#</a> 将部件内容设置为 Twig 变量</h2><p>在任何模板中，你可以使用 <code>partial()</code> 函数将部件内容设置为变量。这允许你在显示之前操作输出。记得使用 <code>|raw</code> 过滤器来防止输出转义。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> cardPartial <span class="token operator">=</span> partial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>

<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> cardPartial<span class="token operator">|</span>raw <span class="token delimiter punctuation">}}</span></span>
</code></pre></div><p>你也可以将变量作为第二个参数传递给部件。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> cardPartial <span class="token operator">=</span> partial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">,</span> <span class="token punctuation">{</span> foo<span class="token punctuation">:</span> <span class="token string"><span class="token punctuation">&#39;</span>bar<span class="token punctuation">&#39;</span></span> <span class="token punctuation">}</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="检查部件是否存在"><a href="#检查部件是否存在" class="header-anchor">#</a> 检查部件是否存在</h2><p><code>hasPartial()</code> 函数可用于在不渲染内容的情况下检查部件是否存在，如果找到部件则返回 true，否则返回 false。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">if</span> hasPartial<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">partial</span> <span class="token string"><span class="token punctuation">&#39;</span>my-cards/card<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">else</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>Card not found!<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endif</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div>`,32))])}const y=e(u,[["render",g]]);export{v as __pageData,y as default};
